"""Evaluate whether declared source dependencies have changed."""

import json

_MISSING = {"kind": "missing"}

def _canonical(state):
    return json.dumps(state, sort_keys=True, separators=(",", ":"))

def evaluate(request, policy):
    """Compare complete saved/current states for relevant declared paths."""
    ignored = set(policy.get("ignored", ()))
    saved = request.get("saved", {})
    current = request.get("current", {})
    changed = sorted({
        path
        for path in request.get("declared", ())
        if path not in ignored
        and _canonical(saved.get(path, _MISSING)) != _canonical(current.get(path, _MISSING))
    })
    return {"needs_review": bool(changed), "changed": changed}
